{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect meeting notes or transcript",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Meeting notes", "Meeting transcript", "Meeting agenda", "Participant list"],
        "outputs": ["Raw meeting content"]
      },
      {
        "id": "A2",
        "name": "Extract decisions and action items",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Raw meeting content", "Meeting agenda", "Participant list"],
        "outputs": ["Decision list", "Action-item assignments with owners", "List of unclear points"]
      },
      {
        "id": "A3",
        "name": "Clarify unclear points with decision owners",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["List of unclear points"],
        "outputs": ["Clarified decisions and action items"]
      },
      {
        "id": "A4",
        "name": "Draft summary email",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Decision list", "Clarified decisions and action items", "Action-item assignments with owners", "Supporting materials (if applicable)"],
        "outputs": ["Draft summary email"]
      },
      {
        "id": "A5",
        "name": "Determine recipient list",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Participant list", "Meeting agenda"],
        "outputs": ["Recipient list"]
      },
      {
        "id": "A6",
        "name": "Send summary email to recipients",
        "actor": "Minute taker",
        "system": "Email client",
        "inputs": ["Draft summary email", "Recipient list"],
        "outputs": ["Sent summary email"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are there unclear points that require clarification from decision owners?",
        "branches": [
          {
            "outcome": "Yes",
            "next": "A3"
          },
          {
            "outcome": "No",
            "next": "A4"
          }
        ]
      },
      {
        "id": "D2",
        "condition": "Is the recipient list complete and valid?",
        "branches": [
          {
            "outcome": "Yes",
            "next": "A6"
          },
          {
            "outcome": "No — incomplete recipient list",
            "next": "A5"
          }
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "description": "Incomplete recipient list: the list of relevant recipients is missing or incorrect, requiring manual resolution before the email can be sent.",
        "handling": "Minute taker must revisit and correct the recipient list before proceeding to send."
      },
      {
        "id": "E2",
        "description": "Decision owner unavailable for clarification: unclear points cannot be resolved because the relevant decision owner is unreachable.",
        "handling": "Not defined in the workflow; handling approach is unknown."
      },
      {
        "id": "E3",
        "description": "Missing or incomplete meeting notes or transcript: insufficient raw content available to produce a summary.",
        "handling": "Not defined in the workflow; handling approach is unknown."
      }
    ],
    "dependencies": [
